  (1, 1, 14, 'Audi Q5 35 TFSI', 'Well maintained Audi Q5 with a complete service history from an authorised workshop. Navigation, heated seats and a rear view camera are fitted. A test drive can be arranged at short notice.', 13890, 'ACTIVE', now() - interval '1958 hours', now() - interval '1958 hours'),
  (2, 2, 5, 'BMW 1 Series 128ti Sport Line', 'Clean BMW 1 Series with a full stamp book and no accident history. The battery health was checked recently and is in very good shape.', 21590, 'ACTIVE', now() - interval '1877 hours', now() - interval '1877 hours'),
  (3, 3, 2, 'Audi Q5 45 TFSI S line', 'Well maintained Audi Q5 with a complete service history from an authorised workshop. Two keys, the full manual set and all service invoices are handed over.', 27590, 'ACTIVE', now() - interval '1241 hours', now() - interval '1241 hours'),
  (4, 4, 13, 'VW Golf 2.0 TDI Life', 'Second owner VW Golf that has spent most of its life on longer motorway runs. Two keys, the full manual set and all service invoices are handed over. Financing can be arranged directly through our partner bank.', 5990, 'ACTIVE', now() - interval '449 hours', now() - interval '449 hours'),
  (5, 5, 12, 'Opel Corsa 1.5 Diesel Elegance', 'Reliable Opel Corsa that has been serviced strictly according to the manufacturer schedule. Air conditioning, cruise control and parking sensors are on board. Sold with a fresh inspection and a fully documented history.', 4990, 'ACTIVE', now() - interval '1308 hours', now() - interval '1308 hours'),
  (6, 6, 9, 'Škoda Octavia 2.0 TDI', 'Second owner Škoda Octavia that has spent most of its life on longer motorway runs. Winter and summer wheels are included in the price. Delivery within northern Germany can be arranged on request.', 8590, 'ACTIVE', now() - interval '1254 hours', now() - interval '1254 hours'),
