  (216, 216, 13, 'Renault Clio dCi 85 Equilibre', 'One owner Renault Clio in very presentable condition inside and out. New brake discs and pads were fitted at the most recent inspection. Trade in of your current vehicle is possible after an on site valuation.', 7090, 'ACTIVE', now() - interval '77 hours', now() - interval '77 hours'),
  (217, 217, 10, 'Tesla Model 3 Long Range AWD', 'Clean Tesla Model 3 with a full stamp book and no accident history. The vehicle runs on original wheels with tyres in good condition.', 38790, 'ACTIVE', now() - interval '1416 hours', now() - interval '1416 hours'),
  (218, 218, 9, 'Ford Focus 1.5 TDCi Trend', 'Tidy Ford Focus sold directly by its owner in Pinneberg, ready to drive away. New brake discs and pads were fitted at the most recent inspection. Financing can be arranged directly through our partner bank.', 5190, 'ACTIVE', now() - interval '306 hours', now() - interval '306 hours'),
  (219, 219, 9, 'BMW 1 Series 120i Advantage', 'One owner BMW 1 Series in very presentable condition inside and out. Navigation, heated seats and a rear view camera are fitted. A test drive can be arranged at short notice.', 6390, 'ACTIVE', now() - interval '2515 hours', now() - interval '2515 hours'),
  (220, 220, 10, 'BMW X3 xDrive20d Luxury Line', 'Well maintained BMW X3 with a complete service history from an authorised workshop. Timing belt and water pump were replaced during the last major service.', 25290, 'ACTIVE', now() - interval '1307 hours', now() - interval '1307 hours');
